[CmdletBinding()]param([string]$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path,[string]$ReportPath='ES/Output/StaticReplay/es-abcd-divergence.json')
$ErrorActionPreference='Stop';$root=(Resolve-Path $ProjectRoot).Path;Import-Module (Join-Path $root 'ES/Automation/ABCD/ESABCDDivergence.psm1') -Force;$h='a'*64;$a=Invoke-ESABCDFiveDirectionDivergence -Requirement 'single-requirement' -SourceHash $h;$b=Invoke-ESABCDFiveDirectionDivergence -Requirement 'single-requirement' -SourceHash $h;$cases=@([pscustomobject]@{case='five-or-more-distinct-directions';status=if($a.directionCount -ge 5 -and @($a.directions.directionId|Sort-Object -Unique).Count -eq $a.directionCount){'passed'}else{'failed'}},[pscustomobject]@{case='deterministic-final-selection';status=if($a.selectedDirectionId -ceq $b.selectedDirectionId -and $a.hash -ceq $b.hash){'passed'}else{'failed'}},[pscustomobject]@{case='no-core-experience-write';status=if(-not $a.reusableCoreWrite -and -not $a.persistedExperienceWrite){'passed'}else{'failed'}});$failed=@($cases|Where-Object status -eq 'failed');$refs=@('ES/Automation/ABCD/ESABCDDivergence.psm1','ES/Automation/ABCD/Test-ESABCDDivergence.ps1');$hashes=[ordered]@{};foreach($r in $refs){$hashes[$r]=(Get-FileHash (Join-Path $root $r) -Algorithm SHA256).Hash.ToLowerInvariant()};$report=[ordered]@{schemaVersion=1;validator='Test-ESABCDDivergence';status=if($failed.Count){'failed'}else{'passed'};staticStatus=if($failed.Count){'static-failed'}else{'static-passed'};runtimeStatus='runtime-not-run';evidenceLevel='S1';capturedUtc=[DateTime]::UtcNow.ToString('o');caseCount=$cases.Count;passedCount=($cases.Count-$failed.Count);failedCount=$failed.Count;cases=$cases;directionCount=$a.directionCount;selectedDirectionId=$a.selectedDirectionId;authorizationKind='read-only';evidenceContractId='es.skill-evidence-receipt';evidenceContractHash=(Get-FileHash (Join-Path $root 'ES/Automation/Contracts/es-skill-evidence-receipt-v1.schema.json') -Algorithm SHA256).Hash.ToLowerInvariant();skillName='es-agent-mechanism-replication';case='abcd-divergence';toolId='es-abcd-divergence-validator';receiptPath=$ReportPath.Replace('\','/');sourceRefs=$refs;sourceRefHashes=$hashes;unityVersion='not-run';claimsNotProven=@('human-level ideation breadth')};$full=if([IO.Path]::IsPathRooted($ReportPath)){$ReportPath}else{Join-Path $root $ReportPath};New-Item -ItemType Directory -Force (Split-Path $full)|Out-Null;[IO.File]::WriteAllText($full,($report|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$report|ConvertTo-Json -Depth 20;if($failed.Count){exit 1}
